define('entra-sync-notification', {
  prefix: 'entra.sync.notification.',
  keys: [
    'inprogress',
    'done',
    'error',
    'noAction'
  ]
});

require(['jquery', 'xwiki-meta', 'xwiki-job-runner', 'xwiki-l10n!entra-sync-notification'],
    function($, xwikiMeta, JobRunner, l10n) {
  const checkSyncJob = function(jobId, notification) {
    const statusDocumentReference = XWiki.Model.resolve('EntraID.Code.SyncJobResource', XWiki.EntityType.DOCUMENT);
    const statusURL = new XWiki.Document(statusDocumentReference).getURL('get');
    return Promise.resolve(new JobRunner({
      createStatusRequest: function(jobId) {
        return {
          url: statusURL,
          data: {
            outputSyntax: 'plain',
            sheet: 'EntraID.Code.SyncJobResource',
            data: 'jobStatus',
            jobId: jobId.join('/')
          }
        };
      }
    }).run(statusURL, [
      {name: 'outputSyntax', value: 'plain'},
      {name: 'sheet', value: 'EntraID.Code.SyncJobResource'},
      {name: 'action', value: 'jobStatus'},
      {name: 'jobId', value: jobId.join('/')},
      {name: 'data', value: 'jobStatus'},
      {name: 'form_token', value: xwikiMeta.form_token}
    ])).then(response => {
      if (response.error) {
        throw new Error(response.error.message);
      }
      notification.replace(new XWiki.widgets.Notification(l10n.get('done'), 'done'));
    }).catch(reason => {
      console.error(reason);
      notification.replace(new XWiki.widgets.Notification(l10n.get('error'), 'error'));
    }).finally(() => {
      $('.entra-sync-action').prop('disabled', false);
    });
  };

  $(document).on('click', '.entra-sync-action', function(event) {
    event.preventDefault();
    const form = $(this).closest('form');
    // Missing when the users of the default configuration are synced.
    const configuration = form.data('configuration');
    const disable = String(form.find('input[name="disable"]').prop('checked'));
    const remove = String(form.find('input[name="remove"]').prop('checked'));
    if (disable === 'false' && remove === 'false') {
      new XWiki.widgets.Notification(l10n.get('noAction'), 'info');
      return;
    }
    const syncButton = $(this).prop('disabled', true);
    const notification = new XWiki.widgets.Notification(l10n.get('inprogress'), 'inprogress');
    const data = {disable, remove};
    // Keep the same job ID as the REST resource.
    const jobId = ['entra', 'users', 'sync'];
    if (configuration !== undefined) {
      data.configuration = String(configuration);
      jobId.push(data.configuration);
    }
    jobId.push(disable, remove);
    $.ajax({
      url: form.attr('action'),
      type: 'POST',
      data
    }).then(() => {
      checkSyncJob(jobId, notification);
    }).catch(xhr => {
      console.error(xhr);
      notification.replace(new XWiki.widgets.Notification(l10n.get('error'), 'error'));
      syncButton.prop('disabled', false);
    });
  });
});

#entra-sync {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
